import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const timestamp = new Date().toISOString().replace(/[:.]/g, "-");

const files = {
  "components/AdminBookSupplierInquiryComposer.tsx": "\"use client\";\n\nimport {\n  AlertTriangle,\n  BookOpen,\n  CheckCircle2,\n  Loader2,\n  Mail,\n  PackagePlus,\n  Save,\n  Search,\n  Send,\n  Settings,\n  Trash2,\n} from \"lucide-react\";\nimport Link from \"next/link\";\nimport { FormEvent, useEffect, useMemo, useState } from \"react\";\n\ntype BookData = {\n  requestedIsbn: string;\n  isbn10: string | null;\n  isbn13: string | null;\n  title: string | null;\n  subtitle: string | null;\n  authors: string[];\n  publisher: string | null;\n  publishedDate: string | null;\n  coverUrl: string | null;\n  recommendedPrice: number | null;\n  priceCurrency: string | null;\n  priceSource: string | null;\n};\n\ntype ExistingProduct = {\n  id: string;\n  name: string;\n  sku: string | null;\n  ean: string | null;\n  imageUrl: string | null;\n  productPrice?: number | null;\n  taxRate?: 7 | 19;\n  isBook?: boolean;\n  priceConfirmationStatus?: string | null;\n  priceSource?: string | null;\n};\n\ntype SearchResponse = {\n  ok?: boolean;\n  message?: string;\n  book?: BookData;\n  existingProduct?: ExistingProduct | null;\n};\n\ntype SupplierPartner = {\n  id: string;\n  name: string;\n  email: string | null;\n  contact_person: string | null;\n  phone: string | null;\n};\n\ntype DraftItem = {\n  isbn: string;\n  title: string;\n  subtitle: string | null;\n  authors: string[];\n  publisher: string | null;\n  publishedDate: string | null;\n  coverUrl: string | null;\n  quantity: number;\n  proposedPriceGross: number | null;\n  proposedTaxRate: 7 | 19;\n  priceSource: string | null;\n  linkedProductId: string | null;\n};\n\ntype CreateInquiryResponse = {\n  ok?: boolean;\n  sent?: boolean;\n  warning?: string | null;\n  message?: string;\n  inquiry?: {\n    id: string;\n    inquiryNumber: string;\n  };\n};\n\nconst STORAGE_KEY = \"handzettel-book-supplier-inquiry-draft-v2\";\nconst LEGACY_STORAGE_KEY = \"handzettel-book-supplier-inquiry-draft-v1\";\n\nfunction normalizeIsbn(value: string) {\n  return value\n    .toUpperCase()\n    .replace(/[^0-9X]/g, \"\")\n    .slice(0, 13);\n}\n\nfunction clean(value: unknown) {\n  return String(value ?? \"\").trim();\n}\n\nfunction normalizePrice(value: unknown) {\n  if (value === null || value === undefined || value === \"\") {\n    return null;\n  }\n\n  const parsed = Number(String(value).replace(\",\", \".\"));\n\n  if (!Number.isFinite(parsed) || parsed <= 0) {\n    return null;\n  }\n\n  return Math.round(parsed * 100) / 100;\n}\n\nfunction formatPrice(value: number | null) {\n  if (value === null) return \"—\";\n\n  return new Intl.NumberFormat(\"de-DE\", {\n    style: \"currency\",\n    currency: \"EUR\",\n  }).format(value);\n}\n\nfunction normalizeDraftItem(value: Partial<DraftItem>): DraftItem | null {\n  const isbn = normalizeIsbn(clean(value.isbn));\n  const title = clean(value.title);\n\n  if ((isbn.length !== 10 && isbn.length !== 13) || !title) {\n    return null;\n  }\n\n  return {\n    isbn,\n    title,\n    subtitle: clean(value.subtitle) || null,\n    authors: Array.isArray(value.authors)\n      ? value.authors.map(clean).filter(Boolean)\n      : [],\n    publisher: clean(value.publisher) || null,\n    publishedDate: clean(value.publishedDate) || null,\n    coverUrl: clean(value.coverUrl) || null,\n    quantity: Math.max(1, Math.min(999, Math.trunc(Number(value.quantity) || 1))),\n    proposedPriceGross: normalizePrice(value.proposedPriceGross),\n    proposedTaxRate: Number(value.proposedTaxRate) === 19 ? 19 : 7,\n    priceSource: clean(value.priceSource) || null,\n    linkedProductId: clean(value.linkedProductId) || null,\n  };\n}\n\nexport default function AdminBookSupplierInquiryComposer() {\n  const [partnerName, setPartnerName] = useState(\"Vogtländische Buchhandlung\");\n  const [partnerEmail, setPartnerEmail] = useState(\"\");\n  const [contactPerson, setContactPerson] = useState(\"\");\n  const [partnerPhone, setPartnerPhone] = useState(\"\");\n\n  const [isbn, setIsbn] = useState(\"\");\n  const [foundBook, setFoundBook] = useState<BookData | null>(null);\n  const [foundExistingProduct, setFoundExistingProduct] =\n    useState<ExistingProduct | null>(null);\n  const [items, setItems] = useState<DraftItem[]>([]);\n  const [adminNote, setAdminNote] = useState(\"\");\n\n  const [isLoadingPartner, setIsLoadingPartner] = useState(true);\n  const [isSavingPartner, setIsSavingPartner] = useState(false);\n  const [isSearching, setIsSearching] = useState(false);\n  const [isCreating, setIsCreating] = useState(false);\n\n  const [errorMessage, setErrorMessage] = useState<string | null>(null);\n  const [successMessage, setSuccessMessage] = useState<string | null>(null);\n  const [createdInquiry, setCreatedInquiry] = useState<{\n    id: string;\n    inquiryNumber: string;\n    sent: boolean;\n  } | null>(null);\n\n  const totalQuantity = useMemo(\n    () => items.reduce((sum, item) => sum + item.quantity, 0),\n    [items],\n  );\n\n  const foundProposedPrice =\n    normalizePrice(foundExistingProduct?.productPrice) ??\n    normalizePrice(foundBook?.recommendedPrice);\n\n  const foundTaxRate: 7 | 19 =\n    foundExistingProduct?.taxRate === 19 ? 19 : 7;\n\n  const foundPriceSource =\n    clean(foundExistingProduct?.priceSource) ||\n    clean(foundBook?.priceSource) ||\n    null;\n\n  useEffect(() => {\n    try {\n      const rawDraft =\n        window.localStorage.getItem(STORAGE_KEY) ||\n        window.localStorage.getItem(LEGACY_STORAGE_KEY);\n\n      if (rawDraft) {\n        const parsed = JSON.parse(rawDraft) as {\n          items?: Array<Partial<DraftItem>>;\n          adminNote?: string;\n        };\n\n        if (Array.isArray(parsed.items)) {\n          setItems(\n            parsed.items\n              .map((item) => normalizeDraftItem(item))\n              .filter((item): item is DraftItem => Boolean(item)),\n          );\n        }\n\n        if (typeof parsed.adminNote === \"string\") {\n          setAdminNote(parsed.adminNote);\n        }\n      }\n    } catch {\n      // Ein defekter lokaler Entwurf blockiert die Oberfläche nicht.\n    }\n  }, []);\n\n  useEffect(() => {\n    try {\n      window.localStorage.setItem(\n        STORAGE_KEY,\n        JSON.stringify({\n          items,\n          adminNote,\n        }),\n      );\n    } catch {\n      // LocalStorage ist nur Komfort, nicht Teil des Kernworkflows.\n    }\n  }, [items, adminNote]);\n\n  useEffect(() => {\n    async function loadPartner() {\n      setIsLoadingPartner(true);\n\n      try {\n        const response = await fetch(\"/api/admin/book-supplier/partner\", {\n          method: \"GET\",\n          cache: \"no-store\",\n        });\n\n        const payload = (await response.json()) as {\n          ok?: boolean;\n          message?: string;\n          partner?: SupplierPartner;\n        };\n\n        if (!response.ok || !payload.ok || !payload.partner) {\n          throw new Error(\n            payload.message || \"Die Partnerdaten konnten nicht geladen werden.\",\n          );\n        }\n\n        setPartnerName(payload.partner.name || \"\");\n        setPartnerEmail(payload.partner.email || \"\");\n        setContactPerson(payload.partner.contact_person || \"\");\n        setPartnerPhone(payload.partner.phone || \"\");\n      } catch (error) {\n        setErrorMessage(\n          error instanceof Error\n            ? error.message\n            : \"Die Partnerdaten konnten nicht geladen werden.\",\n        );\n      } finally {\n        setIsLoadingPartner(false);\n      }\n    }\n\n    void loadPartner();\n  }, []);\n\n  async function savePartner(event: FormEvent<HTMLFormElement>) {\n    event.preventDefault();\n\n    if (isSavingPartner) return;\n\n    setErrorMessage(null);\n    setSuccessMessage(null);\n    setIsSavingPartner(true);\n\n    try {\n      const response = await fetch(\"/api/admin/book-supplier/partner\", {\n        method: \"PUT\",\n        headers: {\n          \"Content-Type\": \"application/json\",\n        },\n        body: JSON.stringify({\n          name: partnerName,\n          email: partnerEmail,\n          contactPerson,\n          phone: partnerPhone,\n        }),\n      });\n\n      const payload = (await response.json()) as {\n        ok?: boolean;\n        message?: string;\n        partner?: SupplierPartner;\n      };\n\n      if (!response.ok || !payload.ok || !payload.partner) {\n        throw new Error(\n          payload.message ||\n            \"Die Partnerdaten konnten nicht gespeichert werden.\",\n        );\n      }\n\n      setSuccessMessage(\"Die Partnerdaten wurden gespeichert.\");\n    } catch (error) {\n      setErrorMessage(\n        error instanceof Error\n          ? error.message\n          : \"Die Partnerdaten konnten nicht gespeichert werden.\",\n      );\n    } finally {\n      setIsSavingPartner(false);\n    }\n  }\n\n  async function searchBook(event: FormEvent<HTMLFormElement>) {\n    event.preventDefault();\n\n    if (isSearching) return;\n\n    const normalized = normalizeIsbn(isbn);\n\n    setErrorMessage(null);\n    setSuccessMessage(null);\n    setCreatedInquiry(null);\n    setFoundBook(null);\n    setFoundExistingProduct(null);\n\n    if (normalized.length !== 10 && normalized.length !== 13) {\n      setErrorMessage(\"Bitte gib eine vollständige ISBN-10 oder ISBN-13 ein.\");\n      return;\n    }\n\n    setIsSearching(true);\n\n    try {\n      const response = await fetch(\n        `/api/admin/products/isbn-search?isbn=${encodeURIComponent(\n          normalized,\n        )}`,\n        {\n          method: \"GET\",\n          cache: \"no-store\",\n        },\n      );\n\n      const payload = (await response.json()) as SearchResponse;\n\n      if (!response.ok || !payload.ok || !payload.book) {\n        throw new Error(\n          payload.message || \"Zu dieser ISBN wurde kein Buch gefunden.\",\n        );\n      }\n\n      setIsbn(normalized);\n      setFoundBook(payload.book);\n      setFoundExistingProduct(payload.existingProduct || null);\n    } catch (error) {\n      setErrorMessage(\n        error instanceof Error\n          ? error.message\n          : \"Die ISBN-Suche konnte nicht ausgeführt werden.\",\n      );\n    } finally {\n      setIsSearching(false);\n    }\n  }\n\n  function addFoundBook() {\n    if (!foundBook) return;\n\n    const normalizedIsbn = normalizeIsbn(\n      foundBook.isbn13 || foundBook.requestedIsbn,\n    );\n\n    if (!normalizedIsbn || !clean(foundBook.title)) {\n      setErrorMessage(\n        \"Das gefundene Buch enthält keine vollständige ISBN oder keinen Titel.\",\n      );\n      return;\n    }\n\n    setItems((current) => {\n      const existingIndex = current.findIndex(\n        (item) => item.isbn === normalizedIsbn,\n      );\n\n      if (existingIndex >= 0) {\n        return current.map((item, index) =>\n          index === existingIndex\n            ? {\n                ...item,\n                quantity: item.quantity + 1,\n              }\n            : item,\n        );\n      }\n\n      return [\n        ...current,\n        {\n          isbn: normalizedIsbn,\n          title: clean(foundBook.title),\n          subtitle: clean(foundBook.subtitle) || null,\n          authors: Array.isArray(foundBook.authors)\n            ? foundBook.authors.map(clean).filter(Boolean)\n            : [],\n          publisher: clean(foundBook.publisher) || null,\n          publishedDate: clean(foundBook.publishedDate) || null,\n          coverUrl: clean(foundBook.coverUrl) || null,\n          quantity: 1,\n          proposedPriceGross: foundProposedPrice,\n          proposedTaxRate: foundTaxRate,\n          priceSource: foundPriceSource,\n          linkedProductId: foundExistingProduct?.id || null,\n        },\n      ];\n    });\n\n    setSuccessMessage(\n      `„${clean(foundBook.title)}“ wurde mit Preis- und Steuerdaten zur Sammelanfrage hinzugefügt.`,\n    );\n    setFoundBook(null);\n    setFoundExistingProduct(null);\n    setIsbn(\"\");\n  }\n\n  function updateItem(isbnValue: string, patch: Partial<DraftItem>) {\n    setItems((current) =>\n      current.map((item) =>\n        item.isbn === isbnValue\n          ? {\n              ...item,\n              ...patch,\n            }\n          : item,\n      ),\n    );\n  }\n\n  function removeItem(isbnValue: string) {\n    setItems((current) => current.filter((item) => item.isbn !== isbnValue));\n  }\n\n  function clearDraft() {\n    setItems([]);\n    setAdminNote(\"\");\n    setFoundBook(null);\n    setFoundExistingProduct(null);\n    setCreatedInquiry(null);\n    setErrorMessage(null);\n    setSuccessMessage(\"Der lokale Entwurf wurde geleert.\");\n  }\n\n  async function createInquiry(sendNow: boolean) {\n    if (isCreating) return;\n\n    setErrorMessage(null);\n    setSuccessMessage(null);\n    setCreatedInquiry(null);\n\n    if (items.length === 0) {\n      setErrorMessage(\n        \"Füge zuerst mindestens ein Buch zur Sammelanfrage hinzu.\",\n      );\n      return;\n    }\n\n    if (sendNow && !partnerEmail.trim()) {\n      setErrorMessage(\n        \"Hinterlege zuerst die E-Mail-Adresse der Vogtländischen Buchhandlung.\",\n      );\n      return;\n    }\n\n    setIsCreating(true);\n\n    try {\n      const response = await fetch(\"/api/admin/book-supplier/inquiries\", {\n        method: \"POST\",\n        headers: {\n          \"Content-Type\": \"application/json\",\n        },\n        body: JSON.stringify({\n          adminNote,\n          sendNow,\n          items,\n        }),\n      });\n\n      const payload = (await response.json()) as CreateInquiryResponse;\n\n      if (!response.ok || !payload.ok || !payload.inquiry) {\n        throw new Error(\n          payload.message || \"Die Sammelanfrage konnte nicht erstellt werden.\",\n        );\n      }\n\n      setCreatedInquiry({\n        id: payload.inquiry.id,\n        inquiryNumber: payload.inquiry.inquiryNumber,\n        sent: Boolean(payload.sent),\n      });\n\n      setItems([]);\n      setAdminNote(\"\");\n      setFoundBook(null);\n      setFoundExistingProduct(null);\n      setIsbn(\"\");\n\n      setSuccessMessage(\n        payload.warning ||\n          (payload.sent\n            ? `Die Anfrage ${payload.inquiry.inquiryNumber} wurde erstellt und versendet.`\n            : `Die Anfrage ${payload.inquiry.inquiryNumber} wurde als Entwurf gespeichert.`),\n      );\n    } catch (error) {\n      setErrorMessage(\n        error instanceof Error\n          ? error.message\n          : \"Die Sammelanfrage konnte nicht erstellt werden.\",\n      );\n    } finally {\n      setIsCreating(false);\n    }\n  }\n\n  return (\n    <section className=\"rounded-[32px] border border-[#C8D8E8] bg-[#EEF4FA] p-5 shadow-sm sm:p-7\">\n      <div className=\"flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between\">\n        <div>\n          <div className=\"inline-flex items-center gap-2 rounded-full bg-white px-3 py-1 text-xs font-black uppercase tracking-[0.16em] text-[#12395F]\">\n            <Mail className=\"h-3.5 w-3.5\" />\n            Vogtländische Buchhandlung\n          </div>\n\n          <h2 className=\"mt-3 text-2xl font-black text-[#102A43]\">\n            Sammelanfrage zu Verfügbarkeit, Preis und Umsatzsteuer\n          </h2>\n\n          <p className=\"mt-2 max-w-3xl text-sm font-semibold leading-6 text-[#52616F]\">\n            Jede Buchposition enthält einen vorgeschlagenen Bruttoverkaufspreis\n            und Umsatzsteuersatz. Die Buchhandlung muss beides bestätigen oder\n            korrigieren. Das zugehörige Produkt bleibt währenddessen aktiv.\n          </p>\n        </div>\n\n        <Link\n          href=\"/admin/buchhandlung/anfragen\"\n          className=\"inline-flex min-h-11 items-center justify-center gap-2 rounded-2xl bg-white px-4 py-3 text-sm font-black text-[#12395F] shadow-sm ring-1 ring-[#C8D8E8] transition hover:bg-[#F5FAFD]\"\n        >\n          <BookOpen className=\"h-4 w-4\" />\n          Anfragen öffnen\n        </Link>\n      </div>\n\n      {errorMessage ? (\n        <div className=\"mt-5 flex items-start gap-3 rounded-2xl border border-[#F0B7BA] bg-[#FFF1F1] p-4 text-[#9F1D24]\">\n          <AlertTriangle className=\"mt-0.5 h-5 w-5 shrink-0\" />\n          <p className=\"text-sm font-bold leading-6\">{errorMessage}</p>\n        </div>\n      ) : null}\n\n      {successMessage ? (\n        <div className=\"mt-5 flex items-start gap-3 rounded-2xl border border-[#BFE3CD] bg-[#F0FFF6] p-4 text-[#2F7D50]\">\n          <CheckCircle2 className=\"mt-0.5 h-5 w-5 shrink-0\" />\n          <div>\n            <p className=\"text-sm font-bold leading-6\">{successMessage}</p>\n\n            {createdInquiry ? (\n              <Link\n                href={`/admin/buchhandlung/anfragen/${createdInquiry.id}`}\n                className=\"mt-2 inline-flex font-black underline\"\n              >\n                {createdInquiry.inquiryNumber} öffnen\n              </Link>\n            ) : null}\n          </div>\n        </div>\n      ) : null}\n\n      <details className=\"mt-5 rounded-[26px] border border-[#C8D8E8] bg-white p-4\">\n        <summary className=\"flex cursor-pointer items-center gap-2 font-black text-[#102A43]\">\n          <Settings className=\"h-4 w-4\" />\n          Partnerdaten und E-Mail-Adresse\n        </summary>\n\n        <form onSubmit={savePartner} className=\"mt-4 grid gap-4 sm:grid-cols-2\">\n          <label className=\"block\">\n            <span className=\"mb-2 block text-sm font-black\">Buchhandlung*</span>\n            <input\n              value={partnerName}\n              onChange={(event) => setPartnerName(event.target.value)}\n              disabled={isLoadingPartner}\n              className=\"min-h-12 w-full rounded-2xl border border-[#D8C8B8] bg-white px-4 font-semibold outline-none focus:border-[#B5282D]\"\n            />\n          </label>\n\n          <label className=\"block\">\n            <span className=\"mb-2 block text-sm font-black\">\n              E-Mail-Adresse*\n            </span>\n            <input\n              type=\"email\"\n              value={partnerEmail}\n              onChange={(event) => setPartnerEmail(event.target.value)}\n              disabled={isLoadingPartner}\n              placeholder=\"bestellung@buchhandlung.de\"\n              className=\"min-h-12 w-full rounded-2xl border border-[#D8C8B8] bg-white px-4 font-semibold outline-none focus:border-[#B5282D]\"\n            />\n          </label>\n\n          <label className=\"block\">\n            <span className=\"mb-2 block text-sm font-black\">\n              Ansprechpartner\n            </span>\n            <input\n              value={contactPerson}\n              onChange={(event) => setContactPerson(event.target.value)}\n              disabled={isLoadingPartner}\n              className=\"min-h-12 w-full rounded-2xl border border-[#D8C8B8] bg-white px-4 font-semibold outline-none focus:border-[#B5282D]\"\n            />\n          </label>\n\n          <label className=\"block\">\n            <span className=\"mb-2 block text-sm font-black\">Telefon</span>\n            <input\n              value={partnerPhone}\n              onChange={(event) => setPartnerPhone(event.target.value)}\n              disabled={isLoadingPartner}\n              className=\"min-h-12 w-full rounded-2xl border border-[#D8C8B8] bg-white px-4 font-semibold outline-none focus:border-[#B5282D]\"\n            />\n          </label>\n\n          <div className=\"sm:col-span-2\">\n            <button\n              type=\"submit\"\n              disabled={isSavingPartner || isLoadingPartner}\n              className=\"inline-flex min-h-11 items-center justify-center gap-2 rounded-2xl bg-[#102A43] px-4 py-3 text-sm font-black text-white disabled:opacity-60\"\n            >\n              {isSavingPartner ? (\n                <Loader2 className=\"h-4 w-4 animate-spin\" />\n              ) : (\n                <Save className=\"h-4 w-4\" />\n              )}\n              Partnerdaten speichern\n            </button>\n          </div>\n        </form>\n      </details>\n\n      <div className=\"mt-5 grid gap-5 xl:grid-cols-[minmax(0,0.9fr)_minmax(0,1.1fr)]\">\n        <div className=\"rounded-[26px] border border-[#C8D8E8] bg-white p-4 sm:p-5\">\n          <h3 className=\"text-lg font-black text-[#102A43]\">ISBN suchen</h3>\n\n          <form\n            onSubmit={searchBook}\n            className=\"mt-4 grid gap-3 sm:grid-cols-[1fr_auto]\"\n          >\n            <input\n              value={isbn}\n              onChange={(event) => setIsbn(normalizeIsbn(event.target.value))}\n              placeholder=\"ISBN-10 oder ISBN-13\"\n              autoComplete=\"off\"\n              className=\"min-h-13 rounded-2xl border border-[#D8C8B8] bg-white px-4 text-lg font-black tracking-[0.06em] outline-none focus:border-[#B5282D]\"\n            />\n\n            <button\n              type=\"submit\"\n              disabled={isSearching}\n              className=\"inline-flex min-h-13 items-center justify-center gap-2 rounded-2xl bg-[#B5282D] px-5 py-3 font-black text-white disabled:opacity-60\"\n            >\n              {isSearching ? (\n                <Loader2 className=\"h-5 w-5 animate-spin\" />\n              ) : (\n                <Search className=\"h-5 w-5\" />\n              )}\n              Suchen\n            </button>\n          </form>\n\n          {foundBook ? (\n            <article className=\"mt-4 rounded-[24px] border border-[#E8DED2] bg-[#FBF7F0] p-4\">\n              <div className=\"flex gap-4\">\n                <div className=\"h-28 w-20 shrink-0 overflow-hidden rounded-xl border border-[#E8DED2] bg-white\">\n                  {foundBook.coverUrl ? (\n                    <img\n                      src={foundBook.coverUrl}\n                      alt={foundBook.title || \"Buchcover\"}\n                      className=\"h-full w-full object-contain p-1\"\n                    />\n                  ) : (\n                    <div className=\"flex h-full items-center justify-center text-[#A75B28]\">\n                      <BookOpen className=\"h-6 w-6\" />\n                    </div>\n                  )}\n                </div>\n\n                <div className=\"min-w-0 flex-1\">\n                  <p className=\"font-black text-[#102A43]\">\n                    {foundBook.title || \"Buchtitel nicht angegeben\"}\n                  </p>\n\n                  {foundBook.subtitle ? (\n                    <p className=\"mt-1 text-sm font-semibold text-[#52616F]\">\n                      {foundBook.subtitle}\n                    </p>\n                  ) : null}\n\n                  <p className=\"mt-2 text-xs font-bold uppercase tracking-[0.08em] text-[#A75B28]\">\n                    ISBN {foundBook.isbn13 || foundBook.requestedIsbn}\n                  </p>\n\n                  {foundBook.publisher ? (\n                    <p className=\"mt-1 text-sm font-semibold text-[#52616F]\">\n                      {foundBook.publisher}\n                    </p>\n                  ) : null}\n                </div>\n              </div>\n\n              <div className=\"mt-4 grid gap-2 sm:grid-cols-2\">\n                <div className=\"rounded-2xl border border-[#BFE3CD] bg-[#F0FFF6] p-3\">\n                  <p className=\"text-xs font-black uppercase text-[#2F7D50]\">\n                    Vorgeschlagener Preis\n                  </p>\n                  <p className=\"mt-1 text-lg font-black text-[#102A43]\">\n                    {formatPrice(foundProposedPrice)}\n                  </p>\n                  <p className=\"mt-1 text-xs font-semibold text-[#52616F]\">\n                    {foundPriceSource || \"Keine Preisquelle gefunden\"}\n                  </p>\n                </div>\n\n                <div className=\"rounded-2xl border border-[#D6E7EF] bg-[#F5FAFD] p-3\">\n                  <p className=\"text-xs font-black uppercase text-[#12395F]\">\n                    Produktverknüpfung\n                  </p>\n                  <p className=\"mt-1 font-black text-[#102A43]\">\n                    {foundExistingProduct\n                      ? \"Produkt im Katalog gefunden\"\n                      : \"Noch kein Produkt verknüpft\"}\n                  </p>\n                  <p className=\"mt-1 text-xs font-semibold text-[#52616F]\">\n                    USt.-Vorschlag: {foundTaxRate} %\n                  </p>\n                </div>\n              </div>\n\n              <button\n                type=\"button\"\n                onClick={addFoundBook}\n                className=\"mt-4 inline-flex min-h-11 w-full items-center justify-center gap-2 rounded-2xl bg-[#102A43] px-4 py-3 text-sm font-black text-white\"\n              >\n                <PackagePlus className=\"h-4 w-4\" />\n                Mit Preisprüfung hinzufügen\n              </button>\n            </article>\n          ) : null}\n        </div>\n\n        <div className=\"rounded-[26px] border border-[#C8D8E8] bg-white p-4 sm:p-5\">\n          <div className=\"flex items-start justify-between gap-4\">\n            <div>\n              <h3 className=\"text-lg font-black text-[#102A43]\">\n                Aktuelle Sammelanfrage\n              </h3>\n              <p className=\"mt-1 text-sm font-semibold text-[#52616F]\">\n                {items.length} ISBN · {totalQuantity} Exemplar(e)\n              </p>\n            </div>\n\n            {items.length > 0 ? (\n              <button\n                type=\"button\"\n                onClick={clearDraft}\n                className=\"inline-flex items-center gap-2 text-xs font-black text-[#B5282D]\"\n              >\n                <Trash2 className=\"h-4 w-4\" />\n                Leeren\n              </button>\n            ) : null}\n          </div>\n\n          {items.length > 0 ? (\n            <div className=\"mt-4 space-y-3\">\n              {items.map((item) => (\n                <article\n                  key={item.isbn}\n                  className=\"rounded-2xl border border-[#E8DED2] bg-[#FBF7F0] p-3\"\n                >\n                  <div className=\"flex items-start gap-3\">\n                    <div className=\"h-20 w-14 shrink-0 overflow-hidden rounded-lg border border-[#E8DED2] bg-white\">\n                      {item.coverUrl ? (\n                        <img\n                          src={item.coverUrl}\n                          alt={item.title}\n                          className=\"h-full w-full object-contain p-1\"\n                        />\n                      ) : (\n                        <div className=\"flex h-full items-center justify-center text-[#A75B28]\">\n                          <BookOpen className=\"h-4 w-4\" />\n                        </div>\n                      )}\n                    </div>\n\n                    <div className=\"min-w-0 flex-1\">\n                      <p className=\"font-black text-[#102A43]\">{item.title}</p>\n                      <p className=\"mt-1 text-xs font-bold text-[#52616F]\">\n                        ISBN {item.isbn}\n                      </p>\n                      <p className=\"mt-1 text-xs font-semibold text-[#52616F]\">\n                        {item.linkedProductId\n                          ? \"Mit aktivem Katalogprodukt verknüpft\"\n                          : \"Ohne Katalogprodukt – Bestätigung wird trotzdem gespeichert\"}\n                      </p>\n                    </div>\n                  </div>\n\n                  <div className=\"mt-3 grid gap-3 sm:grid-cols-3\">\n                    <label className=\"block\">\n                      <span className=\"mb-1 block text-xs font-black\">\n                        Menge\n                      </span>\n                      <input\n                        type=\"number\"\n                        min={1}\n                        max={999}\n                        value={item.quantity}\n                        onChange={(event) =>\n                          updateItem(item.isbn, {\n                            quantity: Math.max(\n                              1,\n                              Math.min(\n                                999,\n                                Math.trunc(Number(event.target.value) || 1),\n                              ),\n                            ),\n                          })\n                        }\n                        className=\"h-11 w-full rounded-xl border border-[#D8C8B8] bg-white px-3 font-black\"\n                      />\n                    </label>\n\n                    <label className=\"block\">\n                      <span className=\"mb-1 block text-xs font-black\">\n                        Preis brutto\n                      </span>\n                      <input\n                        type=\"text\"\n                        inputMode=\"decimal\"\n                        value={\n                          item.proposedPriceGross === null\n                            ? \"\"\n                            : item.proposedPriceGross.toFixed(2).replace(\".\", \",\")\n                        }\n                        onChange={(event) =>\n                          updateItem(item.isbn, {\n                            proposedPriceGross: normalizePrice(event.target.value),\n                            priceSource: item.priceSource || \"Manuelle Admin-Eingabe\",\n                          })\n                        }\n                        placeholder=\"z. B. 16,50\"\n                        className=\"h-11 w-full rounded-xl border border-[#D8C8B8] bg-white px-3 font-black\"\n                      />\n                    </label>\n\n                    <label className=\"block\">\n                      <span className=\"mb-1 block text-xs font-black\">\n                        Umsatzsteuer\n                      </span>\n                      <select\n                        value={item.proposedTaxRate}\n                        onChange={(event) =>\n                          updateItem(item.isbn, {\n                            proposedTaxRate:\n                              event.target.value === \"19\" ? 19 : 7,\n                          })\n                        }\n                        className=\"h-11 w-full rounded-xl border border-[#D8C8B8] bg-white px-3 font-black\"\n                      >\n                        <option value={7}>7 %</option>\n                        <option value={19}>19 %</option>\n                      </select>\n                    </label>\n                  </div>\n\n                  <div className=\"mt-3 flex flex-col gap-2 rounded-xl border border-[#D6E7EF] bg-white p-3 sm:flex-row sm:items-center sm:justify-between\">\n                    <p className=\"text-xs font-semibold leading-5 text-[#52616F]\">\n                      Preisquelle: {item.priceSource || \"Nicht angegeben\"}\n                    </p>\n                    <button\n                      type=\"button\"\n                      onClick={() => removeItem(item.isbn)}\n                      className=\"inline-flex h-9 items-center justify-center gap-2 rounded-xl border border-[#F0B7BA] bg-white px-3 text-xs font-black text-[#B5282D]\"\n                    >\n                      <Trash2 className=\"h-4 w-4\" />\n                      Entfernen\n                    </button>\n                  </div>\n                </article>\n              ))}\n\n              <label className=\"block\">\n                <span className=\"mb-2 block text-sm font-black text-[#102A43]\">\n                  Hinweis an die Buchhandlung\n                </span>\n                <textarea\n                  value={adminNote}\n                  onChange={(event) => setAdminNote(event.target.value)}\n                  rows={4}\n                  placeholder=\"Optionaler Hinweis zur Sammelanfrage\"\n                  className=\"w-full rounded-2xl border border-[#D8C8B8] bg-white p-4 font-semibold outline-none focus:border-[#B5282D]\"\n                />\n              </label>\n\n              <div className=\"rounded-2xl border border-[#F1D1A8] bg-[#FFF8EE] p-4 text-xs font-semibold leading-5 text-[#52616F]\">\n                Die Buchhandlung kann die Rückmeldung zwischenspeichern. Als\n                vollständig beantwortet gilt die Anfrage erst, wenn zu jeder\n                Position Verfügbarkeit, Preis und Umsatzsteuer geprüft wurden.\n              </div>\n\n              <div className=\"grid gap-3 sm:grid-cols-2\">\n                <button\n                  type=\"button\"\n                  onClick={() => void createInquiry(false)}\n                  disabled={isCreating}\n                  className=\"inline-flex min-h-12 items-center justify-center gap-2 rounded-2xl border border-[#C8D8E8] bg-white px-4 py-3 text-sm font-black text-[#12395F] disabled:opacity-60\"\n                >\n                  {isCreating ? (\n                    <Loader2 className=\"h-4 w-4 animate-spin\" />\n                  ) : (\n                    <Save className=\"h-4 w-4\" />\n                  )}\n                  Als Entwurf speichern\n                </button>\n\n                <button\n                  type=\"button\"\n                  onClick={() => void createInquiry(true)}\n                  disabled={isCreating}\n                  className=\"inline-flex min-h-12 items-center justify-center gap-2 rounded-2xl bg-[#B5282D] px-4 py-3 text-sm font-black text-white disabled:opacity-60\"\n                >\n                  {isCreating ? (\n                    <Loader2 className=\"h-4 w-4 animate-spin\" />\n                  ) : (\n                    <Send className=\"h-4 w-4\" />\n                  )}\n                  Speichern und senden\n                </button>\n              </div>\n            </div>\n          ) : (\n            <div className=\"mt-4 rounded-2xl border border-dashed border-[#C8D8E8] bg-[#F5FAFD] p-6 text-center\">\n              <BookOpen className=\"mx-auto h-7 w-7 text-[#12395F]\" />\n              <p className=\"mt-2 font-black text-[#102A43]\">\n                Noch keine Bücher gesammelt\n              </p>\n              <p className=\"mt-1 text-sm font-semibold text-[#52616F]\">\n                Suche links eine ISBN und füge das Buch hinzu.\n              </p>\n            </div>\n          )}\n        </div>\n      </div>\n    </section>\n  );\n}\n",
  "components/BookSupplierResponseForm.tsx": "\"use client\";\n\nimport {\n  AlertTriangle,\n  CheckCircle2,\n  CircleDollarSign,\n  Loader2,\n  Save,\n  Send,\n} from \"lucide-react\";\nimport { useMemo, useState } from \"react\";\n\ntype PriceConfirmationStatus = \"pending\" | \"confirmed\" | \"changed\";\n\ntype InquiryItem = {\n  id: string;\n  isbn: string;\n  title: string;\n  subtitle: string | null;\n  authors: string[] | null;\n  publisher: string | null;\n  cover_url: string | null;\n  requested_quantity: number;\n  availability_status: string;\n  available_quantity: number | null;\n  lead_time_days: number | null;\n  available_from: string | null;\n  reservation_until: string | null;\n  supplier_note: string | null;\n  linked_product_id: string | null;\n  proposed_price_gross: number | null;\n  proposed_tax_rate: number | null;\n  price_source: string | null;\n  price_confirmation_status: PriceConfirmationStatus;\n  confirmed_price_gross: number | null;\n  confirmed_tax_rate: number | null;\n  price_confirmed_at: string | null;\n  price_applied_to_product_at: string | null;\n};\n\ntype Props = {\n  token: string;\n  inquiryNumber: string;\n  initialSupplierNote: string | null;\n  initialItems: InquiryItem[];\n};\n\nconst STATUS_OPTIONS = [\n  [\"pending\", \"Noch nicht beantwortet\"],\n  [\"in_store\", \"Im Laden verfügbar\"],\n  [\"orderable\", \"Bestellbar\"],\n  [\"partially_available\", \"Teilweise verfügbar\"],\n  [\"unavailable\", \"Nicht verfügbar\"],\n  [\"checking\", \"Noch zu prüfen\"],\n] as const;\n\nfunction toPrice(value: unknown) {\n  if (value === null || value === undefined || value === \"\") return null;\n\n  const parsed = Number(String(value).replace(\",\", \".\"));\n\n  if (!Number.isFinite(parsed) || parsed <= 0 || parsed > 5000) {\n    return null;\n  }\n\n  return Math.round(parsed * 100) / 100;\n}\n\nfunction formatPrice(value: number | null) {\n  if (value === null) return \"Nicht angegeben\";\n\n  return new Intl.NumberFormat(\"de-DE\", {\n    style: \"currency\",\n    currency: \"EUR\",\n  }).format(value);\n}\n\nfunction normalizeInitialItem(item: InquiryItem): InquiryItem {\n  const proposedTaxRate = Number(item.proposed_tax_rate) === 19 ? 19 : 7;\n  const confirmedTaxRate =\n    Number(item.confirmed_tax_rate) === 19\n      ? 19\n      : Number(item.confirmed_tax_rate) === 7\n        ? 7\n        : null;\n\n  return {\n    ...item,\n    proposed_price_gross: toPrice(item.proposed_price_gross),\n    proposed_tax_rate: proposedTaxRate,\n    price_confirmation_status:\n      item.price_confirmation_status === \"confirmed\" ||\n      item.price_confirmation_status === \"changed\"\n        ? item.price_confirmation_status\n        : \"pending\",\n    confirmed_price_gross:\n      toPrice(item.confirmed_price_gross) ?? toPrice(item.proposed_price_gross),\n    confirmed_tax_rate: confirmedTaxRate ?? proposedTaxRate,\n  };\n}\n\nexport default function BookSupplierResponseForm({\n  token,\n  inquiryNumber,\n  initialSupplierNote,\n  initialItems,\n}: Props) {\n  const [supplierNote, setSupplierNote] = useState(initialSupplierNote || \"\");\n  const [items, setItems] = useState(() =>\n    initialItems.map(normalizeInitialItem),\n  );\n  const [isSaving, setIsSaving] = useState(false);\n  const [success, setSuccess] = useState<string | null>(null);\n  const [error, setError] = useState<string | null>(null);\n\n  const progress = useMemo(() => {\n    const availabilityDone = items.filter(\n      (item) => item.availability_status !== \"pending\",\n    ).length;\n    const priceDone = items.filter(\n      (item) =>\n        item.price_confirmation_status === \"confirmed\" ||\n        item.price_confirmation_status === \"changed\",\n    ).length;\n\n    return {\n      availabilityDone,\n      priceDone,\n      total: items.length,\n    };\n  }, [items]);\n\n  function updateItem(itemId: string, patch: Partial<InquiryItem>) {\n    setItems((current) =>\n      current.map((item) =>\n        item.id === itemId\n          ? {\n              ...item,\n              ...patch,\n            }\n          : item,\n      ),\n    );\n  }\n\n  function setPriceConfirmation(\n    item: InquiryItem,\n    status: PriceConfirmationStatus,\n  ) {\n    if (status === \"confirmed\" && item.proposed_price_gross === null) {\n      setError(\n        `Für „${item.title}“ fehlt ein vorgeschlagener Preis. Bitte wählen Sie „Preis/USt. ändern“ und tragen Sie den gültigen Preis ein.`,\n      );\n      return;\n    }\n\n    updateItem(item.id, {\n      price_confirmation_status: status,\n      confirmed_price_gross:\n        status === \"confirmed\"\n          ? item.proposed_price_gross\n          : item.confirmed_price_gross ?? item.proposed_price_gross,\n      confirmed_tax_rate:\n        status === \"confirmed\"\n          ? Number(item.proposed_tax_rate) === 19\n            ? 19\n            : 7\n          : item.confirmed_tax_rate ?? item.proposed_tax_rate ?? 7,\n    });\n    setError(null);\n  }\n\n  function validateCompletion() {\n    for (const item of items) {\n      if (item.availability_status === \"pending\") {\n        return `Bitte beantworten Sie zuerst die Verfügbarkeit für „${item.title}“.`;\n      }\n\n      if (item.price_confirmation_status === \"pending\") {\n        return `Bitte bestätigen oder ändern Sie Preis und Umsatzsteuer für „${item.title}“.`;\n      }\n\n      if (\n        item.price_confirmation_status === \"changed\" &&\n        toPrice(item.confirmed_price_gross) === null\n      ) {\n        return `Bitte tragen Sie für „${item.title}“ einen gültigen Bruttopreis ein.`;\n      }\n\n      if (\n        item.confirmed_tax_rate !== 7 &&\n        item.confirmed_tax_rate !== 19\n      ) {\n        return `Bitte wählen Sie für „${item.title}“ einen gültigen Umsatzsteuersatz.`;\n      }\n    }\n\n    return null;\n  }\n\n  async function saveResponse(complete: boolean) {\n    if (isSaving) return;\n\n    if (complete) {\n      const validationError = validateCompletion();\n\n      if (validationError) {\n        setError(validationError);\n        setSuccess(null);\n        return;\n      }\n    }\n\n    setIsSaving(true);\n    setSuccess(null);\n    setError(null);\n\n    try {\n      const response = await fetch(\n        `/api/book-supplier/inquiries/${encodeURIComponent(token)}`,\n        {\n          method: \"PATCH\",\n          headers: {\n            \"Content-Type\": \"application/json\",\n          },\n          body: JSON.stringify({\n            supplierNote,\n            complete,\n            items: items.map((item) => ({\n              id: item.id,\n              availabilityStatus: item.availability_status,\n              availableQuantity: item.available_quantity,\n              leadTimeDays: item.lead_time_days,\n              availableFrom: item.available_from,\n              reservationUntil: item.reservation_until,\n              supplierNote: item.supplier_note,\n              priceConfirmationStatus: item.price_confirmation_status,\n              confirmedPriceGross: item.confirmed_price_gross,\n              confirmedTaxRate: item.confirmed_tax_rate,\n            })),\n          }),\n        },\n      );\n\n      const payload = (await response.json()) as {\n        ok?: boolean;\n        message?: string;\n        items?: InquiryItem[];\n      };\n\n      if (!response.ok || !payload.ok) {\n        throw new Error(\n          payload.message || \"Die Rückmeldung konnte nicht gespeichert werden.\",\n        );\n      }\n\n      if (Array.isArray(payload.items)) {\n        setItems(payload.items.map(normalizeInitialItem));\n      }\n\n      setSuccess(\n        payload.message ||\n          `Die Rückmeldung zu ${inquiryNumber} wurde gespeichert.`,\n      );\n    } catch (caughtError) {\n      setError(\n        caughtError instanceof Error\n          ? caughtError.message\n          : \"Die Rückmeldung konnte nicht gespeichert werden.\",\n      );\n    } finally {\n      setIsSaving(false);\n    }\n  }\n\n  return (\n    <div className=\"grid gap-5\">\n      <section className=\"rounded-[28px] border border-[#C8D8E8] bg-[#EEF4FA] p-5\">\n        <div className=\"flex items-start gap-3\">\n          <CircleDollarSign className=\"mt-0.5 h-6 w-6 shrink-0 text-[#12395F]\" />\n          <div>\n            <h2 className=\"text-lg font-black text-[#102A43]\">\n              Preis und Umsatzsteuer je Position verpflichtend prüfen\n            </h2>\n            <p className=\"mt-1 text-sm font-semibold leading-6 text-[#52616F]\">\n              Der vorgeschlagene Preis kann bestätigt oder korrigiert werden.\n              Bei einer Korrektur wird der neue Wert für zukünftige Verkäufe in\n              das verknüpfte Produkt übernommen. Bereits abgeschlossene Verkäufe\n              bleiben unverändert.\n            </p>\n          </div>\n        </div>\n\n        <div className=\"mt-4 grid gap-3 sm:grid-cols-2\">\n          <div className=\"rounded-2xl bg-white p-3\">\n            <p className=\"text-xs font-black uppercase text-[#12395F]\">\n              Verfügbarkeit beantwortet\n            </p>\n            <p className=\"mt-1 text-xl font-black text-[#102A43]\">\n              {progress.availabilityDone} / {progress.total}\n            </p>\n          </div>\n          <div className=\"rounded-2xl bg-white p-3\">\n            <p className=\"text-xs font-black uppercase text-[#12395F]\">\n              Preis und USt. geprüft\n            </p>\n            <p className=\"mt-1 text-xl font-black text-[#102A43]\">\n              {progress.priceDone} / {progress.total}\n            </p>\n          </div>\n        </div>\n      </section>\n\n      {success ? (\n        <div className=\"flex items-start gap-3 rounded-2xl border border-[#BFE3CD] bg-[#F0FFF6] p-4 text-[#2F7D50]\">\n          <CheckCircle2 className=\"mt-0.5 h-5 w-5 shrink-0\" />\n          <p className=\"font-bold leading-6\">{success}</p>\n        </div>\n      ) : null}\n\n      {error ? (\n        <div className=\"flex items-start gap-3 rounded-2xl border border-[#F0B7BA] bg-[#FFF1F1] p-4 font-bold text-[#9F1D24]\">\n          <AlertTriangle className=\"mt-0.5 h-5 w-5 shrink-0\" />\n          <p>{error}</p>\n        </div>\n      ) : null}\n\n      {items.map((item, index) => (\n        <article\n          key={item.id}\n          className=\"rounded-[28px] border border-[#E8DED2] bg-white p-5 shadow-sm\"\n        >\n          <div className=\"flex flex-col gap-4 sm:flex-row\">\n            <div className=\"h-36 w-24 shrink-0 overflow-hidden rounded-xl border border-[#E8DED2] bg-[#FBF7F0]\">\n              {item.cover_url ? (\n                <img\n                  src={item.cover_url}\n                  alt={item.title}\n                  className=\"h-full w-full object-contain p-1\"\n                />\n              ) : null}\n            </div>\n\n            <div className=\"min-w-0 flex-1\">\n              <p className=\"text-xs font-black uppercase tracking-[0.14em] text-[#A75B28]\">\n                Position {index + 1}\n              </p>\n              <h2 className=\"mt-1 text-xl font-black text-[#102A43]\">\n                {item.title}\n              </h2>\n\n              {item.subtitle ? (\n                <p className=\"mt-1 font-semibold text-[#52616F]\">\n                  {item.subtitle}\n                </p>\n              ) : null}\n\n              <p className=\"mt-2 text-sm font-bold text-[#52616F]\">\n                ISBN {item.isbn} · Angefragt: {item.requested_quantity}{\" \"}\n                Exemplar(e)\n              </p>\n            </div>\n          </div>\n\n          <div className=\"mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n            <label className=\"block\">\n              <span className=\"mb-2 block text-sm font-black\">\n                Verfügbarkeit*\n              </span>\n              <select\n                value={item.availability_status}\n                onChange={(event) =>\n                  updateItem(item.id, {\n                    availability_status: event.target.value,\n                  })\n                }\n                className=\"min-h-12 w-full rounded-2xl border border-[#D8C8B8] bg-white px-4 font-bold\"\n              >\n                {STATUS_OPTIONS.map(([value, label]) => (\n                  <option key={value} value={value}>\n                    {label}\n                  </option>\n                ))}\n              </select>\n            </label>\n\n            <label className=\"block\">\n              <span className=\"mb-2 block text-sm font-black\">\n                Verfügbare Menge\n              </span>\n              <input\n                type=\"number\"\n                min={0}\n                value={item.available_quantity ?? \"\"}\n                onChange={(event) =>\n                  updateItem(item.id, {\n                    available_quantity:\n                      event.target.value === \"\"\n                        ? null\n                        : Number(event.target.value),\n                  })\n                }\n                className=\"min-h-12 w-full rounded-2xl border border-[#D8C8B8] bg-white px-4 font-bold\"\n              />\n            </label>\n\n            <label className=\"block\">\n              <span className=\"mb-2 block text-sm font-black\">\n                Lieferzeit in Tagen\n              </span>\n              <input\n                type=\"number\"\n                min={0}\n                value={item.lead_time_days ?? \"\"}\n                onChange={(event) =>\n                  updateItem(item.id, {\n                    lead_time_days:\n                      event.target.value === \"\"\n                        ? null\n                        : Number(event.target.value),\n                  })\n                }\n                className=\"min-h-12 w-full rounded-2xl border border-[#D8C8B8] bg-white px-4 font-bold\"\n              />\n            </label>\n\n            <label className=\"block\">\n              <span className=\"mb-2 block text-sm font-black\">\n                Verfügbar ab\n              </span>\n              <input\n                type=\"date\"\n                value={item.available_from || \"\"}\n                onChange={(event) =>\n                  updateItem(item.id, {\n                    available_from: event.target.value || null,\n                  })\n                }\n                className=\"min-h-12 w-full rounded-2xl border border-[#D8C8B8] bg-white px-4 font-bold\"\n              />\n            </label>\n\n            <label className=\"block\">\n              <span className=\"mb-2 block text-sm font-black\">\n                Reserviert bis\n              </span>\n              <input\n                type=\"date\"\n                value={item.reservation_until || \"\"}\n                onChange={(event) =>\n                  updateItem(item.id, {\n                    reservation_until: event.target.value || null,\n                  })\n                }\n                className=\"min-h-12 w-full rounded-2xl border border-[#D8C8B8] bg-white px-4 font-bold\"\n              />\n            </label>\n          </div>\n\n          <div className=\"mt-5 rounded-[24px] border border-[#F1D1A8] bg-[#FFF8EE] p-4\">\n            <p className=\"text-xs font-black uppercase tracking-[0.14em] text-[#A75B28]\">\n              Gebundener Verkaufspreis und Umsatzsteuer\n            </p>\n\n            <div className=\"mt-3 grid gap-3 sm:grid-cols-3\">\n              <div className=\"rounded-2xl border border-[#F1D1A8] bg-white p-3\">\n                <p className=\"text-xs font-black text-[#52616F]\">\n                  Vorschlag\n                </p>\n                <p className=\"mt-1 text-lg font-black text-[#102A43]\">\n                  {formatPrice(item.proposed_price_gross)}\n                </p>\n                <p className=\"mt-1 text-xs font-semibold text-[#52616F]\">\n                  USt. {Number(item.proposed_tax_rate) === 19 ? 19 : 7} %\n                </p>\n              </div>\n\n              <button\n                type=\"button\"\n                onClick={() => setPriceConfirmation(item, \"confirmed\")}\n                className={`rounded-2xl border p-3 text-left transition ${\n                  item.price_confirmation_status === \"confirmed\"\n                    ? \"border-[#2F7D50] bg-[#F0FFF6] ring-2 ring-[#2F7D50]/20\"\n                    : \"border-[#D8C8B8] bg-white hover:border-[#2F7D50]\"\n                }`}\n              >\n                <p className=\"text-sm font-black text-[#102A43]\">\n                  Preis und USt. bestätigen\n                </p>\n                <p className=\"mt-1 text-xs font-semibold leading-5 text-[#52616F]\">\n                  Vorschlag unverändert übernehmen.\n                </p>\n              </button>\n\n              <button\n                type=\"button\"\n                onClick={() => setPriceConfirmation(item, \"changed\")}\n                className={`rounded-2xl border p-3 text-left transition ${\n                  item.price_confirmation_status === \"changed\"\n                    ? \"border-[#B5282D] bg-[#FFF1F1] ring-2 ring-[#B5282D]/15\"\n                    : \"border-[#D8C8B8] bg-white hover:border-[#B5282D]\"\n                }`}\n              >\n                <p className=\"text-sm font-black text-[#102A43]\">\n                  Preis/USt. ändern\n                </p>\n                <p className=\"mt-1 text-xs font-semibold leading-5 text-[#52616F]\">\n                  Gültigen Wert korrigiert eintragen.\n                </p>\n              </button>\n            </div>\n\n            {item.price_confirmation_status === \"changed\" ? (\n              <div className=\"mt-4 grid gap-3 sm:grid-cols-2\">\n                <label className=\"block\">\n                  <span className=\"mb-2 block text-sm font-black\">\n                    Korrigierter Bruttopreis*\n                  </span>\n                  <input\n                    type=\"text\"\n                    inputMode=\"decimal\"\n                    value={\n                      item.confirmed_price_gross === null\n                        ? \"\"\n                        : item.confirmed_price_gross\n                            .toFixed(2)\n                            .replace(\".\", \",\")\n                    }\n                    onChange={(event) =>\n                      updateItem(item.id, {\n                        confirmed_price_gross: toPrice(event.target.value),\n                      })\n                    }\n                    placeholder=\"z. B. 16,50\"\n                    className=\"min-h-12 w-full rounded-2xl border border-[#D8C8B8] bg-white px-4 font-bold\"\n                  />\n                </label>\n\n                <label className=\"block\">\n                  <span className=\"mb-2 block text-sm font-black\">\n                    Korrigierter Umsatzsteuersatz*\n                  </span>\n                  <select\n                    value={item.confirmed_tax_rate === 19 ? 19 : 7}\n                    onChange={(event) =>\n                      updateItem(item.id, {\n                        confirmed_tax_rate:\n                          event.target.value === \"19\" ? 19 : 7,\n                      })\n                    }\n                    className=\"min-h-12 w-full rounded-2xl border border-[#D8C8B8] bg-white px-4 font-bold\"\n                  >\n                    <option value={7}>7 %</option>\n                    <option value={19}>19 %</option>\n                  </select>\n                </label>\n              </div>\n            ) : null}\n\n            <div className=\"mt-3 rounded-2xl border border-[#F1D1A8] bg-white p-3 text-xs font-semibold leading-5 text-[#52616F]\">\n              Preisquelle: {item.price_source || \"Nicht angegeben\"}\n              {item.linked_product_id\n                ? \" · Verknüpftes Produkt wird nach Bestätigung aktualisiert.\"\n                : \" · Kein Produkt verknüpft; die Rückmeldung bleibt an der Anfrage gespeichert.\"}\n            </div>\n          </div>\n\n          <label className=\"mt-5 block\">\n            <span className=\"mb-2 block text-sm font-black\">\n              Bemerkung zur Position\n            </span>\n            <textarea\n              rows={3}\n              value={item.supplier_note || \"\"}\n              onChange={(event) =>\n                updateItem(item.id, {\n                  supplier_note: event.target.value,\n                })\n              }\n              className=\"w-full rounded-2xl border border-[#D8C8B8] bg-white p-4 font-semibold\"\n            />\n          </label>\n        </article>\n      ))}\n\n      <label className=\"block rounded-[28px] border border-[#E8DED2] bg-white p-5 shadow-sm\">\n        <span className=\"mb-2 block text-sm font-black\">\n          Allgemeine Rückmeldung\n        </span>\n        <textarea\n          rows={4}\n          value={supplierNote}\n          onChange={(event) => setSupplierNote(event.target.value)}\n          className=\"w-full rounded-2xl border border-[#D8C8B8] bg-white p-4 font-semibold\"\n        />\n      </label>\n\n      <div className=\"grid gap-3 sm:grid-cols-2\">\n        <button\n          type=\"button\"\n          onClick={() => void saveResponse(false)}\n          disabled={isSaving}\n          className=\"inline-flex min-h-14 items-center justify-center gap-2 rounded-2xl border border-[#C8D8E8] bg-white px-6 py-4 text-base font-black text-[#12395F] disabled:opacity-60\"\n        >\n          {isSaving ? (\n            <Loader2 className=\"h-5 w-5 animate-spin\" />\n          ) : (\n            <Save className=\"h-5 w-5\" />\n          )}\n          Zwischenstand speichern\n        </button>\n\n        <button\n          type=\"button\"\n          onClick={() => void saveResponse(true)}\n          disabled={isSaving}\n          className=\"inline-flex min-h-14 items-center justify-center gap-2 rounded-2xl bg-[#B5282D] px-6 py-4 text-base font-black text-white disabled:opacity-60\"\n        >\n          {isSaving ? (\n            <Loader2 className=\"h-5 w-5 animate-spin\" />\n          ) : (\n            <Send className=\"h-5 w-5\" />\n          )}\n          Rückmeldung vollständig abschließen\n        </button>\n      </div>\n    </div>\n  );\n}\n",
  "app/api/admin/book-supplier/inquiries/route.ts": "import { requireAdminApiSession } from \"@/app/lib/adminApiAuth\";\nimport { NextResponse } from \"next/server\";\nimport { supabaseServer } from \"@/lib/supabase/server\";\nimport { sendBookSupplierInquiryMail } from \"@/lib/bookSupplierMail\";\n\nexport const dynamic = \"force-dynamic\";\nexport const runtime = \"nodejs\";\n\nconst PARTNER_SLUG = \"vogtlaendische-buchhandlung\";\n\nfunction clean(value: unknown) {\n  return String(value ?? \"\").trim();\n}\n\nfunction normalizeIsbn(value: unknown) {\n  return clean(value)\n    .toUpperCase()\n    .replace(/[^0-9X]/g, \"\")\n    .slice(0, 13);\n}\n\nfunction toQuantity(value: unknown) {\n  const parsed = Math.trunc(Number(value));\n\n  if (!Number.isFinite(parsed)) {\n    return 1;\n  }\n\n  return Math.max(1, Math.min(999, parsed));\n}\n\nfunction toPositivePrice(value: unknown) {\n  if (value === null || value === undefined || value === \"\") {\n    return null;\n  }\n\n  const parsed = Number(String(value).replace(\",\", \".\"));\n\n  if (!Number.isFinite(parsed) || parsed <= 0 || parsed > 5000) {\n    return null;\n  }\n\n  return Math.round(parsed * 100) / 100;\n}\n\nfunction toTaxRate(value: unknown): 7 | 19 {\n  return Number(value) === 19 ? 19 : 7;\n}\n\nasync function loadPartner() {\n  const { data, error } = await supabaseServer\n    .from(\"book_supplier_partners\")\n    .select(\"*\")\n    .eq(\"slug\", PARTNER_SLUG)\n    .eq(\"is_active\", true)\n    .maybeSingle();\n\n  if (error) {\n    throw new Error(\n      `Partnerdaten konnten nicht geladen werden: ${error.message}`,\n    );\n  }\n\n  if (!data) {\n    throw new Error(\n      \"Die Vogtländische Buchhandlung ist noch nicht als aktiver Partner angelegt.\",\n    );\n  }\n\n  return data;\n}\n\nasync function nextInquiryNumber() {\n  const { data, error } = await supabaseServer.rpc(\n    \"next_book_supplier_inquiry_number\",\n  );\n\n  if (!error && typeof data === \"string\" && data.trim()) {\n    return data.trim();\n  }\n\n  return `VB-${new Date().getFullYear()}-${Date.now().toString().slice(-8)}`;\n}\n\nasync function findBookProduct(isbn: string) {\n  const candidates = [isbn];\n\n  for (const candidate of candidates) {\n    const { data, error } = await supabaseServer\n      .from(\"school_products\")\n      .select(\n        \"id,ean,price,tax_rate,is_book,book_isbn10,book_isbn13,book_price_source,book_price_confirmation_status\",\n      )\n      .or(\n        `ean.eq.${candidate},book_isbn10.eq.${candidate},book_isbn13.eq.${candidate}`,\n      )\n      .limit(1)\n      .maybeSingle();\n\n    if (error) {\n      throw new Error(\n        `Produktverknüpfung für ISBN ${candidate} fehlgeschlagen: ${error.message}`,\n      );\n    }\n\n    if (data) {\n      return data;\n    }\n  }\n\n  return null;\n}\n\nexport async function GET() {\n  const unauthorized = await requireAdminApiSession();\n  if (unauthorized) return unauthorized;\n\n  try {\n    const { data, error } = await supabaseServer\n      .from(\"book_supplier_inquiries\")\n      .select(\"*\")\n      .order(\"created_at\", {\n        ascending: false,\n      })\n      .limit(250);\n\n    if (error) {\n      throw new Error(\n        `Anfragen konnten nicht geladen werden: ${error.message}`,\n      );\n    }\n\n    return NextResponse.json({\n      ok: true,\n      inquiries: data || [],\n    });\n  } catch (error) {\n    return NextResponse.json(\n      {\n        ok: false,\n        message:\n          error instanceof Error\n            ? error.message\n            : \"Die Anfragen konnten nicht geladen werden.\",\n      },\n      { status: 500 },\n    );\n  }\n}\n\nexport async function POST(request: Request) {\n  const unauthorized = await requireAdminApiSession();\n  if (unauthorized) return unauthorized;\n\n  let createdInquiryId: string | null = null;\n\n  try {\n    const body = (await request.json()) as {\n      adminNote?: unknown;\n      sendNow?: unknown;\n      items?: Array<{\n        isbn?: unknown;\n        title?: unknown;\n        subtitle?: unknown;\n        authors?: unknown;\n        publisher?: unknown;\n        publishedDate?: unknown;\n        coverUrl?: unknown;\n        quantity?: unknown;\n        proposedPriceGross?: unknown;\n        proposedTaxRate?: unknown;\n        priceSource?: unknown;\n        linkedProductId?: unknown;\n      }>;\n    };\n\n    const rawItems = Array.isArray(body.items) ? body.items : [];\n\n    if (rawItems.length === 0) {\n      return NextResponse.json(\n        {\n          ok: false,\n          message: \"Füge zuerst mindestens ein Buch zur Sammelanfrage hinzu.\",\n        },\n        { status: 400 },\n      );\n    }\n\n    if (rawItems.length > 100) {\n      return NextResponse.json(\n        {\n          ok: false,\n          message: \"Eine Sammelanfrage darf höchstens 100 ISBNs enthalten.\",\n        },\n        { status: 400 },\n      );\n    }\n\n    const partner = await loadPartner();\n\n    const byIsbn = new Map<\n      string,\n      {\n        isbn: string;\n        title: string;\n        subtitle: string | null;\n        authors: string[];\n        publisher: string | null;\n        published_date: string | null;\n        cover_url: string | null;\n        requested_quantity: number;\n        linked_product_id: string | null;\n        proposed_price_gross: number | null;\n        proposed_tax_rate: 7 | 19;\n        price_source: string | null;\n        price_confirmation_status: \"pending\";\n        confirmed_price_gross: null;\n        confirmed_tax_rate: null;\n        price_confirmed_at: null;\n        price_applied_to_product_at: null;\n      }\n    >();\n\n    for (const rawItem of rawItems) {\n      const isbn = normalizeIsbn(rawItem.isbn);\n      const title = clean(rawItem.title);\n\n      if ((isbn.length !== 10 && isbn.length !== 13) || !title) {\n        return NextResponse.json(\n          {\n            ok: false,\n            message:\n              \"Mindestens eine Buchposition enthält keine gültige ISBN oder keinen Titel.\",\n          },\n          { status: 400 },\n        );\n      }\n\n      const quantity = toQuantity(rawItem.quantity);\n      const existing = byIsbn.get(isbn);\n\n      if (existing) {\n        existing.requested_quantity = Math.min(\n          999,\n          existing.requested_quantity + quantity,\n        );\n        continue;\n      }\n\n      const product = await findBookProduct(isbn);\n      const productPrice = toPositivePrice(product?.price);\n      const clientPrice = toPositivePrice(rawItem.proposedPriceGross);\n      const proposedPrice = productPrice ?? clientPrice;\n      const proposedTaxRate = product\n        ? toTaxRate(product.tax_rate)\n        : toTaxRate(rawItem.proposedTaxRate);\n\n      byIsbn.set(isbn, {\n        isbn,\n        title,\n        subtitle: clean(rawItem.subtitle) || null,\n        authors: Array.isArray(rawItem.authors)\n          ? rawItem.authors.map(clean).filter(Boolean)\n          : [],\n        publisher: clean(rawItem.publisher) || null,\n        published_date: clean(rawItem.publishedDate) || null,\n        cover_url: clean(rawItem.coverUrl) || null,\n        requested_quantity: quantity,\n        linked_product_id: product?.id || null,\n        proposed_price_gross: proposedPrice,\n        proposed_tax_rate: proposedTaxRate,\n        price_source:\n          clean(product?.book_price_source) ||\n          clean(rawItem.priceSource) ||\n          (proposedPrice ? \"Admin-Vorschlag\" : null),\n        price_confirmation_status: \"pending\",\n        confirmed_price_gross: null,\n        confirmed_tax_rate: null,\n        price_confirmed_at: null,\n        price_applied_to_product_at: null,\n      });\n    }\n\n    const inquiryNumber = await nextInquiryNumber();\n    const adminNote = clean(body.adminNote);\n    const sendNow = body.sendNow === true;\n\n    const { data: inquiry, error: inquiryError } = await supabaseServer\n      .from(\"book_supplier_inquiries\")\n      .insert({\n        inquiry_number: inquiryNumber,\n        supplier_id: partner.id,\n        status: \"draft\",\n        admin_note: adminNote || null,\n      })\n      .select(\"*\")\n      .single();\n\n    if (inquiryError || !inquiry) {\n      throw new Error(\n        `Sammelanfrage konnte nicht angelegt werden: ${\n          inquiryError?.message || \"unbekannter Fehler\"\n        }`,\n      );\n    }\n\n    createdInquiryId = inquiry.id;\n\n    const rows = Array.from(byIsbn.values()).map((item, index) => ({\n      inquiry_id: inquiry.id,\n      sort_order: index + 1,\n      ...item,\n    }));\n\n    const { error: itemsError } = await supabaseServer\n      .from(\"book_supplier_inquiry_items\")\n      .insert(rows);\n\n    if (itemsError) {\n      throw new Error(\n        `Buchpositionen konnten nicht gespeichert werden: ${itemsError.message}`,\n      );\n    }\n\n    await supabaseServer.from(\"book_supplier_events\").insert({\n      inquiry_id: inquiry.id,\n      event_type: \"inquiry_created\",\n      title: \"Sammelanfrage erstellt\",\n      description: `${rows.length} ISBN-Positionen mit Preis- und Steuerprüfung wurden erfasst.`,\n      metadata: {\n        item_count: rows.length,\n        total_quantity: rows.reduce(\n          (sum, item) => sum + item.requested_quantity,\n          0,\n        ),\n        linked_product_count: rows.filter((item) => item.linked_product_id).length,\n        proposed_price_count: rows.filter(\n          (item) => item.proposed_price_gross !== null,\n        ).length,\n      },\n    });\n\n    let sent = false;\n    let warning: string | null = null;\n\n    if (sendNow) {\n      try {\n        await sendBookSupplierInquiryMail({\n          partner,\n          inquiry,\n          items: rows,\n        });\n\n        const now = new Date().toISOString();\n\n        await supabaseServer\n          .from(\"book_supplier_inquiries\")\n          .update({\n            status: \"sent\",\n            sent_at: now,\n            sent_to_email: partner.email,\n            updated_at: now,\n          })\n          .eq(\"id\", inquiry.id);\n\n        await supabaseServer.from(\"book_supplier_events\").insert({\n          inquiry_id: inquiry.id,\n          event_type: \"inquiry_sent\",\n          title: \"Buchanfrage gesendet\",\n          description: `Die Anfrage wurde an ${partner.email} gesendet.`,\n          metadata: {\n            recipient: partner.email,\n          },\n        });\n\n        sent = true;\n      } catch (mailError) {\n        warning =\n          mailError instanceof Error\n            ? `Die Anfrage wurde gespeichert, aber nicht versendet: ${mailError.message}`\n            : \"Die Anfrage wurde gespeichert, aber nicht versendet.\";\n      }\n    }\n\n    return NextResponse.json({\n      ok: true,\n      sent,\n      warning,\n      message: sent\n        ? `Die Anfrage ${inquiryNumber} wurde erstellt und versendet.`\n        : `Die Anfrage ${inquiryNumber} wurde gespeichert.`,\n      inquiry: {\n        id: inquiry.id,\n        inquiryNumber,\n      },\n    });\n  } catch (error) {\n    if (createdInquiryId) {\n      await supabaseServer\n        .from(\"book_supplier_inquiries\")\n        .delete()\n        .eq(\"id\", createdInquiryId);\n    }\n\n    return NextResponse.json(\n      {\n        ok: false,\n        message:\n          error instanceof Error\n            ? error.message\n            : \"Die Sammelanfrage konnte nicht erstellt werden.\",\n      },\n      { status: 500 },\n    );\n  }\n}\n",
  "app/api/book-supplier/inquiries/[token]/route.ts": "import { NextResponse } from \"next/server\";\nimport { supabaseServer } from \"@/lib/supabase/server\";\nimport { sendBookSupplierResponseNotification } from \"@/lib/bookSupplierMail\";\n\nexport const dynamic = \"force-dynamic\";\nexport const runtime = \"nodejs\";\n\nconst ALLOWED_STATUSES = new Set([\n  \"pending\",\n  \"in_store\",\n  \"orderable\",\n  \"partially_available\",\n  \"unavailable\",\n  \"checking\",\n]);\n\nconst ALLOWED_PRICE_STATUSES = new Set([\n  \"pending\",\n  \"confirmed\",\n  \"changed\",\n]);\n\ntype Params = {\n  params: Promise<{\n    token: string;\n  }>;\n};\n\ntype RawItemUpdate = {\n  id?: unknown;\n  availabilityStatus?: unknown;\n  availableQuantity?: unknown;\n  leadTimeDays?: unknown;\n  availableFrom?: unknown;\n  reservationUntil?: unknown;\n  supplierNote?: unknown;\n  priceConfirmationStatus?: unknown;\n  confirmedPriceGross?: unknown;\n  confirmedTaxRate?: unknown;\n};\n\nfunction clean(value: unknown) {\n  return String(value ?? \"\").trim();\n}\n\nfunction nullableNumber(value: unknown) {\n  if (value === null || value === undefined || value === \"\") {\n    return null;\n  }\n\n  const parsed = Math.trunc(Number(value));\n\n  if (!Number.isFinite(parsed) || parsed < 0) {\n    return null;\n  }\n\n  return parsed;\n}\n\nfunction nullablePrice(value: unknown) {\n  if (value === null || value === undefined || value === \"\") {\n    return null;\n  }\n\n  const parsed = Number(String(value).replace(\",\", \".\"));\n\n  if (!Number.isFinite(parsed) || parsed <= 0 || parsed > 5000) {\n    return null;\n  }\n\n  return Math.round(parsed * 100) / 100;\n}\n\nfunction nullableTaxRate(value: unknown): 7 | 19 | null {\n  if (Number(value) === 7) return 7;\n  if (Number(value) === 19) return 19;\n  return null;\n}\n\nfunction nullableDate(value: unknown) {\n  const text = clean(value);\n\n  return /^\\d{4}-\\d{2}-\\d{2}$/.test(text) ? text : null;\n}\n\nasync function loadInquiry(token: string) {\n  const { data: inquiry, error: inquiryError } = await supabaseServer\n    .from(\"book_supplier_inquiries\")\n    .select(\"*\")\n    .eq(\"response_token\", token)\n    .maybeSingle();\n\n  if (inquiryError) {\n    throw new Error(\n      `Anfrage konnte nicht geladen werden: ${inquiryError.message}`,\n    );\n  }\n\n  if (!inquiry) {\n    return null;\n  }\n\n  const [\n    { data: partner, error: partnerError },\n    { data: items, error: itemsError },\n  ] = await Promise.all([\n    supabaseServer\n      .from(\"book_supplier_partners\")\n      .select(\"*\")\n      .eq(\"id\", inquiry.supplier_id)\n      .maybeSingle(),\n    supabaseServer\n      .from(\"book_supplier_inquiry_items\")\n      .select(\"*\")\n      .eq(\"inquiry_id\", inquiry.id)\n      .order(\"sort_order\", {\n        ascending: true,\n      }),\n  ]);\n\n  if (partnerError || !partner) {\n    throw new Error(\n      `Buchhandlung konnte nicht geladen werden: ${\n        partnerError?.message || \"Partner fehlt\"\n      }`,\n    );\n  }\n\n  if (itemsError) {\n    throw new Error(\n      `Buchpositionen konnten nicht geladen werden: ${itemsError.message}`,\n    );\n  }\n\n  return {\n    inquiry,\n    partner,\n    items: items || [],\n  };\n}\n\nfunction resolvePriceDecision(\n  item: Record<string, unknown>,\n  rawUpdate: RawItemUpdate,\n) {\n  const status = clean(rawUpdate.priceConfirmationStatus);\n\n  if (!ALLOWED_PRICE_STATUSES.has(status)) {\n    throw new Error(\n      `Für „${clean(item.title)}“ wurde kein gültiger Preisprüfstatus übermittelt.`,\n    );\n  }\n\n  if (status === \"pending\") {\n    return {\n      status: \"pending\" as const,\n      confirmedPrice: null,\n      confirmedTaxRate: null,\n    };\n  }\n\n  const proposedPrice = nullablePrice(item.proposed_price_gross);\n  const proposedTaxRate = nullableTaxRate(item.proposed_tax_rate);\n\n  if (status === \"confirmed\") {\n    if (proposedPrice === null || proposedTaxRate === null) {\n      throw new Error(\n        `Der Preisvorschlag für „${clean(item.title)}“ ist unvollständig. Bitte wählen Sie „Preis/USt. ändern“.`,\n      );\n    }\n\n    return {\n      status: \"confirmed\" as const,\n      confirmedPrice: proposedPrice,\n      confirmedTaxRate: proposedTaxRate,\n    };\n  }\n\n  const confirmedPrice = nullablePrice(rawUpdate.confirmedPriceGross);\n  const confirmedTaxRate = nullableTaxRate(rawUpdate.confirmedTaxRate);\n\n  if (confirmedPrice === null || confirmedTaxRate === null) {\n    throw new Error(\n      `Bitte tragen Sie für „${clean(item.title)}“ einen gültigen Bruttopreis und Umsatzsteuersatz ein.`,\n    );\n  }\n\n  return {\n    status: \"changed\" as const,\n    confirmedPrice,\n    confirmedTaxRate,\n  };\n}\n\nasync function applyPriceToLinkedProduct(params: {\n  item: Record<string, unknown>;\n  price: number;\n  taxRate: 7 | 19;\n  status: \"confirmed\" | \"changed\";\n  supplierId: string;\n  now: string;\n}) {\n  const linkedProductId = clean(params.item.linked_product_id);\n\n  if (!linkedProductId) {\n    return null;\n  }\n\n  const { error } = await supabaseServer\n    .from(\"school_products\")\n    .update({\n      price: params.price,\n      tax_rate: params.taxRate,\n      book_price_confirmation_status: params.status,\n      book_price_confirmed_at: params.now,\n      book_price_confirmed_by_supplier_id: params.supplierId,\n      book_price_last_checked_at: params.now,\n      updated_at: params.now,\n    })\n    .eq(\"id\", linkedProductId);\n\n  if (error) {\n    throw new Error(\n      `Preis für das verknüpfte Produkt „${clean(params.item.title)}“ konnte nicht aktualisiert werden: ${error.message}`,\n    );\n  }\n\n  return params.now;\n}\n\nexport async function GET(_request: Request, context: Params) {\n  try {\n    const { token } = await context.params;\n    const result = await loadInquiry(token);\n\n    if (!result) {\n      return NextResponse.json(\n        {\n          ok: false,\n          message: \"Die Buchanfrage wurde nicht gefunden.\",\n        },\n        { status: 404 },\n      );\n    }\n\n    return NextResponse.json({\n      ok: true,\n      ...result,\n    });\n  } catch (error) {\n    return NextResponse.json(\n      {\n        ok: false,\n        message:\n          error instanceof Error\n            ? error.message\n            : \"Die Buchanfrage konnte nicht geladen werden.\",\n      },\n      { status: 500 },\n    );\n  }\n}\n\nexport async function PATCH(request: Request, context: Params) {\n  try {\n    const { token } = await context.params;\n    const result = await loadInquiry(token);\n\n    if (!result) {\n      return NextResponse.json(\n        {\n          ok: false,\n          message: \"Die Buchanfrage wurde nicht gefunden.\",\n        },\n        { status: 404 },\n      );\n    }\n\n    if (result.inquiry.status === \"closed\") {\n      return NextResponse.json(\n        {\n          ok: false,\n          message: \"Diese Anfrage wurde bereits geschlossen.\",\n        },\n        { status: 409 },\n      );\n    }\n\n    const body = (await request.json()) as {\n      supplierNote?: unknown;\n      complete?: unknown;\n      items?: RawItemUpdate[];\n    };\n\n    const updates = Array.isArray(body.items) ? body.items : [];\n    const completeRequested = body.complete === true;\n    const validItems = new Map(\n      result.items.map((item) => [item.id, item as Record<string, unknown>]),\n    );\n    const rawUpdatesById = new Map<string, RawItemUpdate>();\n\n    for (const rawUpdate of updates) {\n      const itemId = clean(rawUpdate.id);\n      const availabilityStatus = clean(rawUpdate.availabilityStatus);\n\n      if (\n        !itemId ||\n        !validItems.has(itemId) ||\n        !ALLOWED_STATUSES.has(availabilityStatus)\n      ) {\n        return NextResponse.json(\n          {\n            ok: false,\n            message:\n              \"Mindestens eine Rückmeldung enthält eine ungültige Position oder einen ungültigen Verfügbarkeitsstatus.\",\n          },\n          { status: 400 },\n        );\n      }\n\n      rawUpdatesById.set(itemId, rawUpdate);\n    }\n\n    if (completeRequested && rawUpdatesById.size !== result.items.length) {\n      return NextResponse.json(\n        {\n          ok: false,\n          message:\n            \"Zum vollständigen Abschluss müssen alle Buchpositionen übermittelt werden.\",\n        },\n        { status: 400 },\n      );\n    }\n\n    const preparedUpdates = updates.map((rawUpdate) => {\n      const itemId = clean(rawUpdate.id);\n      const item = validItems.get(itemId);\n\n      if (!item) {\n        throw new Error(\"Eine Buchposition konnte nicht zugeordnet werden.\");\n      }\n\n      const availabilityStatus = clean(rawUpdate.availabilityStatus);\n      const priceDecision = resolvePriceDecision(item, rawUpdate);\n\n      if (completeRequested && availabilityStatus === \"pending\") {\n        throw new Error(\n          `Bitte beantworten Sie die Verfügbarkeit für „${clean(item.title)}“.`,\n        );\n      }\n\n      if (completeRequested && priceDecision.status === \"pending\") {\n        throw new Error(\n          `Bitte bestätigen oder ändern Sie Preis und Umsatzsteuer für „${clean(item.title)}“.`,\n        );\n      }\n\n      return {\n        itemId,\n        item,\n        rawUpdate,\n        availabilityStatus,\n        priceDecision,\n      };\n    });\n\n    const now = new Date().toISOString();\n\n    for (const prepared of preparedUpdates) {\n      let appliedAt: string | null = null;\n\n      if (\n        prepared.priceDecision.status === \"confirmed\" ||\n        prepared.priceDecision.status === \"changed\"\n      ) {\n        appliedAt = await applyPriceToLinkedProduct({\n          item: prepared.item,\n          price: prepared.priceDecision.confirmedPrice,\n          taxRate: prepared.priceDecision.confirmedTaxRate,\n          status: prepared.priceDecision.status,\n          supplierId: result.partner.id,\n          now,\n        });\n      }\n\n      const { error: updateError } = await supabaseServer\n        .from(\"book_supplier_inquiry_items\")\n        .update({\n          availability_status: prepared.availabilityStatus,\n          available_quantity: nullableNumber(\n            prepared.rawUpdate.availableQuantity,\n          ),\n          lead_time_days: nullableNumber(prepared.rawUpdate.leadTimeDays),\n          available_from: nullableDate(prepared.rawUpdate.availableFrom),\n          reservation_until: nullableDate(\n            prepared.rawUpdate.reservationUntil,\n          ),\n          supplier_note: clean(prepared.rawUpdate.supplierNote) || null,\n          price_confirmation_status: prepared.priceDecision.status,\n          confirmed_price_gross: prepared.priceDecision.confirmedPrice,\n          confirmed_tax_rate: prepared.priceDecision.confirmedTaxRate,\n          price_confirmed_at:\n            prepared.priceDecision.status === \"pending\" ? null : now,\n          price_applied_to_product_at: appliedAt,\n          updated_at: now,\n        })\n        .eq(\"id\", prepared.itemId)\n        .eq(\"inquiry_id\", result.inquiry.id);\n\n      if (updateError) {\n        throw new Error(\n          `Rückmeldung konnte nicht gespeichert werden: ${updateError.message}`,\n        );\n      }\n    }\n\n    const { data: refreshedItems, error: refreshError } = await supabaseServer\n      .from(\"book_supplier_inquiry_items\")\n      .select(\"*\")\n      .eq(\"inquiry_id\", result.inquiry.id)\n      .order(\"sort_order\", {\n        ascending: true,\n      });\n\n    if (refreshError) {\n      throw new Error(\n        `Gespeicherte Rückmeldung konnte nicht erneut geladen werden: ${refreshError.message}`,\n      );\n    }\n\n    const finalItems = refreshedItems || [];\n    const availabilityAnsweredCount = finalItems.filter(\n      (item) => item.availability_status !== \"pending\",\n    ).length;\n    const priceAnsweredCount = finalItems.filter(\n      (item) =>\n        item.price_confirmation_status === \"confirmed\" ||\n        item.price_confirmation_status === \"changed\",\n    ).length;\n\n    const allCompleted =\n      finalItems.length > 0 &&\n      availabilityAnsweredCount === finalItems.length &&\n      priceAnsweredCount === finalItems.length;\n\n    if (completeRequested && !allCompleted) {\n      throw new Error(\n        \"Die Anfrage konnte nicht abgeschlossen werden, weil mindestens eine Verfügbarkeits- oder Preisprüfung offen ist.\",\n      );\n    }\n\n    const hasProgress =\n      availabilityAnsweredCount > 0 || priceAnsweredCount > 0;\n\n    const nextStatus = allCompleted\n      ? \"answered\"\n      : hasProgress\n        ? \"partially_answered\"\n        : result.inquiry.sent_at\n          ? \"sent\"\n          : \"draft\";\n\n    const { error: inquiryUpdateError } = await supabaseServer\n      .from(\"book_supplier_inquiries\")\n      .update({\n        status: nextStatus,\n        supplier_note: clean(body.supplierNote) || null,\n        first_answered_at:\n          result.inquiry.first_answered_at || (hasProgress ? now : null),\n        answered_at: allCompleted ? now : null,\n        updated_at: now,\n      })\n      .eq(\"id\", result.inquiry.id);\n\n    if (inquiryUpdateError) {\n      throw new Error(\n        `Anfragestatus konnte nicht gespeichert werden: ${inquiryUpdateError.message}`,\n      );\n    }\n\n    await supabaseServer.from(\"book_supplier_events\").insert({\n      inquiry_id: result.inquiry.id,\n      event_type: \"supplier_response_saved\",\n      title: allCompleted\n        ? \"Buchanfrage vollständig beantwortet\"\n        : \"Zwischenstand gespeichert\",\n      description: `${availabilityAnsweredCount} von ${finalItems.length} Verfügbarkeiten und ${priceAnsweredCount} von ${finalItems.length} Preis-/USt.-Prüfungen wurden beantwortet.`,\n      metadata: {\n        availability_answered_count: availabilityAnsweredCount,\n        price_answered_count: priceAnsweredCount,\n        item_count: finalItems.length,\n        status: nextStatus,\n        complete: allCompleted,\n      },\n    });\n\n    try {\n      await sendBookSupplierResponseNotification({\n        partner: result.partner,\n        inquiry: result.inquiry,\n        items: finalItems,\n      });\n    } catch (mailError) {\n      console.error(\"Book supplier response notification failed:\", mailError);\n    }\n\n    return NextResponse.json({\n      ok: true,\n      message: allCompleted\n        ? \"Vielen Dank. Verfügbarkeit, Preis und Umsatzsteuer wurden vollständig gespeichert.\"\n        : \"Der Zwischenstand wurde gespeichert. Offene Positionen können später ergänzt werden.\",\n      status: nextStatus,\n      complete: allCompleted,\n      items: finalItems,\n    });\n  } catch (error) {\n    return NextResponse.json(\n      {\n        ok: false,\n        message:\n          error instanceof Error\n            ? error.message\n            : \"Die Rückmeldung konnte nicht gespeichert werden.\",\n      },\n      { status: 500 },\n    );\n  }\n}\n"
};

for (const [relativePath, content] of Object.entries(files)) {
  const targetPath = path.join(root, ...relativePath.split("/"));

  if (!fs.existsSync(targetPath)) {
    throw new Error(`Datei nicht gefunden: ${relativePath}`);
  }

  const backupPath = `${targetPath}.before-book-price-confirmation-stage2a-${timestamp}.bak`;
  fs.copyFileSync(targetPath, backupPath);
  fs.writeFileSync(targetPath, content.replace(/\r\n/g, "\n"), "utf8");

  console.log(`Aktualisiert: ${relativePath}`);
  console.log(`Backup: ${path.relative(root, backupPath)}`);
}

